/**
 * Private object storage for patient photos, signatures and clinic files.
 * Objects are never public: the app reads them and serves them only after an access check.
 * Implementations: local disk (development) and, later, Cloudflare R2.
 */
export interface ObjectStorage {
  put(key: string, body: Uint8Array, contentType: string): Promise<void>;
  /** Null when the object doesn't exist. */
  get(key: string): Promise<{ body: Uint8Array; contentType: string } | null>;
  delete(key: string): Promise<void>;
}

const KEY = /^[a-z0-9][a-z0-9/_.-]{0,255}$/;

/** Keys are generated by the app, never from user input; this guards against path tricks anyway. */
export function assertSafeKey(key: string): void {
  if (!KEY.test(key) || key.includes("..") || key.includes("//")) throw new Error("Invalid storage key");
}
